// Üretilen dosya: tool/ozgun/uret.py. Kimya ve Malzeme · Laboratuvar güvenliği, cam araç-gereçler, ayırma-saflaştırma yöntemleri ve titrasyon-nitel analiz uygulamaları (kolay).
const ozChemistry17Kolay = <(String, String, List<String>, String)>[
  ('Derişik sülfürik asit seyreltilirken sıçrama riskini önlemek için hangi sıra izlenmelidir?', 'Su üzerine yavaşça asit eklenmeli', ['Asit üzerine hızlıca su dökülmeli', 'İkisi aynı anda kaba boşaltılmalı', 'Asit ısıtıldıktan sonra su katılmalı'], 'Ekzotermik çözünme ısısının su kütlesi tarafından güvenle soğurulması için daima suyun üzerine damla damla ve karıştırılarak asit eklenir.'),
  ('Titrasyon işlemlerinde harcanan sıvı hacmini hassas olarak ölçmeye yarayan altı musluklu dereceli cam boru hangisidir?', 'Büret', ['Beherglas', 'Kroze', 'Desikatör'], 'Büret, alt kısmındaki musluk sayesinde sıvıyı damla damla akıtarak titrasyonda harcanan hacmi hassas biçimde belirlemeyi sağlar.'),
  ('Belirli derişimde standart çözelti hazırlamak için boynunda tek bir ölçü çizgisi bulunan cam kap hangisidir?', 'Balon joje', ['Erlenmayer', 'Ayırma hunisi', 'Saat camı'], 'Balon joje, boyun kısmındaki kalibrasyon çizgisine kadar doldurulduğunda tam ve hassas hacimde çözelti hazırlamak için tasarlanmıştır.'),
  ('Birbiriyle karışmayan zeytinyağı ve su gibi heterojen sıvı-sıvı karışımlarını yoğunluk farkıyla ayırmada hangi cam malzeme kullanılır?', 'Ayırma hunisi', ['Geri soğutucu', 'Dereceli silindir', 'Cam baget'], 'Ayırma hunisi, alttaki musluğu yardımıyla yoğunluğu büyük olan sıvı fazın alt kısımdan kontrollü biçimde ayrılmasını sağlar.'),
  ('Kimya laboratuvarında çözeltileri karıştırmak ve aktarma sırasında sıvının sıçramasını önlemek için kullanılan dolu cam çubuğa ne ad verilir?', 'Baget', ['Spatül', 'Pipet', 'Büret'], 'Baget, kimyasal maddelerle tepkimeye girmeyen pürüzsüz cam yapısıyla karıştırma ve süzme işlemlerinde rehberlik amacıyla kullanılır.'),
  ('GHS piktogramlarında el ve metal yüzey üzerine damlayan sıvı ile aşındırma gösteren sembol hangi tehlikeyi ifade eder?', 'Korozif madde', ['Yakıcı madde', 'Patlayıcı madde', 'Radyoaktif madde'], 'El ve metal yüzeyi aşındıran damla piktogramı, hem canlı dokuya hem de metallere zarar veren korozif (aşındırıcı) maddeleri belirtir.'),
  ('GHS tehlike sembollerinde içi boş bir daire (O harfi) üzerindeki alev figürü hangi kimyasal özelliği gösterir?', 'Oksitleyici (yakıcı)', ['Alevlenebilir (yanıcı)', 'Basınçlı gaz', 'Çevreye zararlı'], 'Daire üzerindeki alev piktogramı, ortama oksijen vererek yanmayı başlatan veya hızlandıran oksitleyici (yakıcı) maddeleri simgeler.'),
  ('Kuru tutmak veya nem çekmesini önlemek amacıyla kurutulmuş numunelerin saklandığı kalın duvarlı kapaklı cam kap hangisidir?', 'Desikatör', ['Erlenmayer', 'Beherglas', 'Mezür'], 'Desikatör, alt bölmesindeki silika jel veya kalsiyum klorür gibi nem çekiciler sayesinde maddeleri nemsiz ortamda soğutup saklar.'),
  ('Yüksek sıcaklıklarda katı maddeleri kül haline getirmek veya kızdırmak için kullanılan fincan biçimli porselen veya metal kap hangisidir?', 'Kroze', ['Balon joje', 'Saat camı', 'Ayırma hunisi'], 'Kroze, porselen, platin veya nikelden üretilen ve çok yüksek fırın ya da bek sıcaklıklarına dayanabilen küçük yakma kabıdır.'),
  ('Kaynama sırasında oluşan buharları yoğunlaştırarak tekrar tepkime kabına döndüren çift cidarlı cam düzenek hangisidir?', 'Geri soğutucu', ['Büret', 'Desikatör', 'Dereceli silindir'], 'Geri soğutucu (reflüks kondansatörü), dış ceketinden geçen soğuk su yardımıyla çözücü buharlarını yoğuşturup madde kaybını önler.'),
  ('GHS sisteminde kurukafa ve çapraz kemikler piktogramı kimyasal maddenin hangi özelliğini bildirir?', 'Akut toksik', ['Aşındırıcı ve tahriş edici', 'Sıkıştırılmış basınçlı gaz', 'Su ortamı için tehlikeli'], 'Kurukafa ve çapraz kemikler sembolü; yutulduğunda, solunduğunda veya deriyle temasta ölümcül olabilen akut toksik maddeleri gösterir.'),
  ('Konik gövdesi ve dar boynu sayesinde çalkalama sırasında sıvı sıçramasını en aza indiren, titrasyonlarda büretin altına konulan cam kap hangisidir?', 'Erlenmayer', ['Beherglas', 'Saat camı', 'Kroze'], 'Erlenmayer, yukarı doğru daralan konik yapısı sayesinde çözeltilerin dökülmeden çalkalanmasına olanak tanıdığı için titrasyonda tercih edilir.'),
  ('Silindirik gövdeli, ağız kısmında sıvı aktarmayı kolaylaştıran oluğu (gagası) bulunan ve ısıtmaya dayanıklı genel amaçlı cam kap hangisidir?', 'Beherglas', ['Balon joje', 'Ayırma hunisi', 'Büret'], 'Beherglas; çözelti hazırlama, ısıtma, kristallendirme ve sıvı aktarma gibi kaba işlemlerde kullanılan oluklu silindirik cam malzemedir.'),
  ('Çok küçük sıvı hacimlerini bir kaptan diğerine hassas biçimde aktarmak için puar ile birlikte kullanılan ince cam boru hangisidir?', 'Pipet', ['Mezür', 'Erlenmayer', 'Kroze'], 'Dereceli veya bullu pipetler, ağızla çekilmeden puar yardımıyla mililitre düzeyindeki sıvı hacimlerini yüksek hassasiyetle taşır.'),
  ('GHS piktogramlarında kurumuş ağaç ve ölü balık figürü hangi tehlike sınıfını temsil eder?', 'Sucul çevre için tehlikeli', ['Patlama riski taşıyan madde', 'Solunum yolunu tahriş eden', 'Yüksek basınçlı sıvılaştırılmış gaz'], 'Ağaç ve ters dönmüş balık sembolü, sucul organizmalar üzerinde kısa veya uzun süreli toksik etki bırakan çevreye zararlı maddeleri gösterir.'),
  ('Laboratuvarda göze kimyasal madde sıçradığında ilk yapılması gereken acil güvenlik uygulaması hangisidir?', 'Göz yıkama duşunda bol suyla en az 15 dakika yıkamak', ['Gözü ovuşturarak kimyasalın dağılmasını sağlamak', 'Nötrleştirmek için göze seyreltik baz damlatmak', 'Gözü kapatıp kuru pamukla tampon uygulamak'], 'Göze sıçrayan kimyasallar göz kapakları açık tutularak göz duşunda temiz su ile en az 15 dakika boyunca kesintisiz yıkanmalıdır.'),
  ('Uçucu, zehirli veya kötü kokulu gaz çıkışı olan deneylerin güvenli biçimde yürütüldüğü havalandırmalı kabine ne ad verilir?', 'Çeker ocak', ['Etüv fırını', 'Otoklav cihazı', 'Desikatör kabı'], 'Çeker ocak, zararlı buhar ve gazları çalışma ortamına yayılmadan emerek filtreleyen veya dışarı atan güvenlik kabinidir.'),
  ('GHS etiketlerinde ünlem işareti (!) piktogramı aşağıdakilerden hangisini belirtmek için kullanılır?', 'Cilt ve göz tahrişi veya hafif akut toksisite', ['Radyoaktif çekirdek bozunması tehlikesi', 'Şiddetli şokla patlayabilen kararsız yapı', 'Yüksek vakum altında ezilme tehlikesi'], 'Ünlem işareti; cilt/göz tahrişi, cilt hassasiyeti, solunum yolu tahrişi, narkotik etki veya ozon tabakasına zararlılık gibi uyarıları bildirir.'),
  ('Sıvıların hacmini yaklaşık ancak beherglasa göre daha doğru ölçmek için kullanılan tabanlı dikey ölçekli cam kap hangisidir?', 'Dereceli silindir', ['Ayırma hunisi', 'Kroze kapağı', 'Cam baget'], 'Dereceli silindir (mezür), üzerindeki mililitre bölmeleri sayesinde saf sıvıların ve çözeltilerin hacmini ölçmek için kullanılır.'),
  ('GHS piktogramlarında insan silüetinin göğüs bölgesinde yıldız benzeri yayılım gösteren sembol hangi tehlikeyi anlatır?', 'Kanserojen, mutajen veya solunum hassaslaştırıcı ciddi sağlık tehlikesi', ['Yalnızca açık alevle temas ettiğinde tutuşabilen katı madde', 'Metaller üzerinde paslanma yapan düşük derişimli tuz çözeltisi', 'Doğrudan güneş ışığında rengi solan organik boyarmadde'], 'Göğüste yıldız (sağlık tehlikesi) sembolü; kanserojenite, üreme toksisitesi, hedef organ hasarı ve aspirasyon tehlikesi gibi kronik/ağır etkileri gösterir.'),
  ('Pipetle asit veya baz çekerken sıvının ağza gelmesini önlemek için pipetin üst ucuna takılan kauçuk yardımcı malzeme hangisidir?', 'Puar', ['Baget', 'Kroze maşası', 'Üçayak'], 'Puar, üç valfli veya pompa mekanizmalı yapısıyla pipet içerisine güvenli vakum uygulayarak sıvıların ağız kullanılmadan çekilmesini sağlar.'),
  ('GHS sisteminde gaz tüpü (silindir) piktogramı bulunan bir kimyasal kap hangi riski taşır?', 'Basınç altındaki gazları içerdiğinden ısındığında patlayabilir', ['Suyla temas ettiğinde kendiliğinden radyoaktif ışıma yayar', 'Açık havada bırakıldığında ortamdaki tüm nemi anında dondurur', 'Yalnızca biyolojik enfeksiyon etkeni olan virüsleri barındırır'], 'Gaz tüpü sembolü; sıkıştırılmış, sıvılaştırılmış veya çözünmüş gazları gösterir; ısıtıldığında patlama ya da soğutulmuşsa soğuk yanığı riski taşır.'),
  ('GHS piktogramlarında etrafa parçalar saçarak patlayan küre sembolü hangi madde grubunu tanımlar?', 'Patlayıcı veya kendiliğinden tepkimeye giren kararsız maddeler', ['Düşük buhar basınçlı ve yanmayan soy gaz karışımları', 'Nötr pH değerine sahip seyreltik sulu şeker çözeltileri', 'Yalnızca sucul bitkilerde büyümeyi hızlandıran gübreler'], 'Patlayan bomba piktogramı; darbe, sürtünme, kıvılcım veya ısı etkisiyle patlayabilen kararsız kimyasalları ve organik peroksitleri belirtir.'),
  ('Laboratuvarda hidroflorik asit (HF) çözeltisi cam şişede saklanamaz; bunun temel kimyasal nedeni nedir?', 'Camın yapısındaki silisyum dioksit ile tepkimeye girerek camı aşındırması', ['Camın ışık geçirgenliği yüzünden asidin anında saf suya dönüşmesi', 'Hidroflorik asidin yalnızca plastik kaplarla ekzotermik patlama yapması', 'Cam yüzeyin asidi dondurarak katı kristal haline getirmesi'], 'Hidroflorik asit, zayıf bir asit olmasına rağmen camdaki silisyum dioksit (SiO2) ile tepkimeye girip uçucu SiF4 oluşturduğu için plastik (polietilen/teflon) kaplarda saklanır.'),
  ('Katı kimyasal maddeleri şişesinden alıp tartım kabına aktarmak için kullanılan kaşık veya düz uçlu metal/porselen yardımcı malzeme hangisidir?', 'Spatül', ['Baget', 'Büret', 'Puar'], 'Spatül, toz veya granül halindeki katı kimyasalları el değmeden temiz ve kontrollü biçimde aktarmaya yarayan kaşık benzeri laboratuvar gerecidir.'),
  ('Az miktardaki katıları kurutmak, tartmak veya beherglasın ağzını gevşekçe kapatmak için kullanılan içbükey dairesel cam malzeme hangisidir?', 'Saat camı', ['Erlenmayer', 'Kroze', 'Ayırma hunisi'], 'Saat camı; içbükey ince yapısıyla az miktarda katı tartımı, kristallendirme ve beherglas üzerine sıçrama önleyici kapak olarak kullanılır.'),
  ('GHS piktogramlarında düz bir çizgi üzerinde yükselen "alev" sembolü hangi madde grubunu ifade eder?', 'Yanıcı (alevlenebilir) gaz, sıvı veya katı maddeler', ['Yalnızca metalleri paslandıran seyreltik tuzlar', 'Su ortamında çözünmeyen asal seramik tozları', 'Basınç altında sıvılaştırılmış yanmayan helyum gazı'], 'Çizgi üzerindeki alev piktogramı; alevlenebilir gazları, aerosolleri, sıvıları, katıları ve suyla temasta yanıcı gaz çıkaran maddeleri belirtir.'),
  ('Sıcak kroze veya porselen kapsülleri fırından ve bek alevinden güvenli biçimde tutmak için kullanılan metal kıskaç hangisidir?', 'Kroze maşası', ['Cam baget', 'Kauçuk puar', 'Büret kıskacı'], 'Kroze maşası, yüksek sıcaklıktaki porselen veya metal krozeleri el yakmadan kavrayıp desikatöre taşımak için tasarlanmış makas biçimli metal alettir.'),
  ('Katı maddeleri toz haline getirmek ve ezmek için birlikte kullanılan çukur kap ve tokmak ikilisine ne ad verilir?', 'Havan ve havan eli', ['Kroze ve desikatör', 'Beherglas ve baget', 'Balon joje ve tıpa'], 'Porselen, akik veya camdan yapılan havan ve havan eli, iri kristalli katı kimyasalların öğütülerek yüzey alanının artırılmasında kullanılır.'),
  ('Büreti dikey konumda sarsılmadan sabitlemek için kullanılan metal çubuklu ağır tabanlı destek aracına ne denir?', 'Spor (destek standı) ve büret kıskacı', ['Üçayak ve kil üçgen', 'Ayırma hunisi halkası', 'Desikatör plakası'], 'Büret, dikey okuma hatası oluşmaması için ağır tabanlı metal spor çubuğuna kelebek/büret kıskacı yardımıyla tam dik olarak tutturulur.'),
  ('Süzme işleminde katı tanecikleri tutmak için süzgeç kağıdının yerleştirildiği konik ağızlı, ince borulu cam malzeme hangisidir?', 'Cam huni', ['Saat camı', 'Dereceli silindir', 'Geri soğutucu'], 'Cam huni, içine katlanarak yerleştirilen süzgeç kağıdı ile heterojen katı-sıvı karışımlarının süzülmesinde ve dar ağızlı kaplara sıvı aktarımında kullanılır.'),
  ('İçerisine saf su doldurulan ve gövdesi sıkıldığında ince uçlu borusundan su püskürten plastik laboratuvar şişesine ne ad verilir?', 'Pisuar', ['Polietilen desikatör', 'Damlalıklı büret', 'Vakumlu nuçe erleni'], 'Yıkama şişesi (piset), çökeltileri yıkamak, erlenmayer çeperini durulamak ve balon jojeyi ölçü çizgisine hassas tamamlamak için saf su püskürtür.'),
  ('Porselen krozeyi bek alevi üzerinde doğrudan ısıtırken üçayak üstüne konulan tel ve seramik borulu üçgen desteğe ne ad verilir?', 'Kil üçgen', ['Tel kafes', 'Büret kıskacı', 'Saat camı'], 'Kil üçgen (porselen üçgen), yüksek sıcaklığa dayanıklı yapısıyla konik tabanlı krozenin doğrudan açık bek aleviyle temas ederek kızdırılmasını sağlar.'),
  ('Laboratuvar çalışmalarında kimyasal sıçramalarına karşı gözleri korumak için takılması zorunlu temel kişisel koruyucu donanım hangisidir?', 'Yan korumalı koruyucu gözlük', ['Pamuklu toz maskesi', 'Kısa kollu laboratuvar önlüğü', 'Numarasız güneş gözlüğü'], 'Yan siperlikli koruyucu gözlük (veya yüz siperi), her yönden gelebilecek sıvı sıçraması ve kırık cam parçalarına karşı gözleri korur.'),
  ('Damıtma ve kaynatma işlemlerinde ısıyı homojen dağıtan küresel gövdeli, uzun boyunlu cam kaba ne ad verilir?', 'Cam balon', ['Beherglas', 'Dereceli pipet', 'Kroze'], 'Küresel gövdeli cam balonlar, köşesiz yapıları sayesinde ısıyı ve iç basıncı eşit dağıttıkları için geri soğutucu ve damıtma düzeneklerinde tercih edilir.'),
  ('Laboratuvarda kırılan cam malzemelerin toplanıp atılması gereken yer neresidir?', 'Kesici-delici ve kırık cam atık kutusu', ['Evsel kağıt geri dönüşüm sepeti', 'Organik çözücü atık bidonu', 'Yemekhane çöp kovası'], 'Kırık camlar çöp poşetlerini delerek temizlik personeline zarar verebileceğinden yalnızca kalın duvarlı özel "kırık cam atık kutusu"na atılır.'),
  ('Bir kimyasal şişesinden alınan ancak deneyde artan reaktif madde ile ilgili doğru kural hangisidir?', 'Kirlenmeyi önlemek için orijinal şişesine kesinlikle geri dökülmez', ['Tasarruf sağlamak amacıyla doğrudan ana stok şişesine geri boşaltılır', 'Ağzı açık bir beherglasta bir sonraki haftaya kadar tezgahta bekletilir', 'Lavaboya dökülüp üzerine çamaşır suyu eklenerek imha edilir'], 'Stok şişeden alınan kimyasalın fazlasını geri dökmek tüm ana stoğun kontamine olmasına veya istenmeyen tepkimelere yol açacağından kesinlikle yasaktır.'),
  ('Kimyasal maddelerin tehlike özelliklerini, ilk yardım önlemlerini, yangınla mücadele ve bertaraf bilgilerini ayrıntılı içeren 16 bölümlük resmi belgeye ne denir?', 'Güvenlik Bilgi Formu', ['Deney Sonuç Raporu', 'Cihaz Kalibrasyon Sertifikası', 'Satın Alma Faturası'], 'Güvenlik Bilgi Formu (SDS/MSDS), her kimyasalın fiziksel/kimyasal tehlikelerini, GHS etiket bilgilerini, KKD gereksinimlerini ve acil müdahale adımlarını açıklar.'),
  ('Laboratuvarda bir kimyasalın kokusunu kontrol etmek kesinlikle gerektiğinde hangi yöntem uygulanmalıdır?', 'Şişeyi uzakta tutup el yardımıyla buharı hafifçe buruna doğru yelpazelemek', ['Burnu şişenin ağzına dayayıp ciğerlere derin bir nefes çekmek', 'Şişeyi önce ısıtıp yoğun buhar çıkarken yakından koklamak', 'Sıvıdan birkaç damla avuç içine döküp ovuşturarak koklamak'], 'Doğrudan koklamak solunum yollarında yanık veya akut zehirlenmeye yol açar; zorunlu hallerde kap uzakta tutulup el hareketiyle çok az buhar buruna yönlendirilir.'),
  ('Laboratuvar ortamında yiyecek ve içecek tüketilmesinin kesin olarak yasaklanmasının temel nedeni nedir?', 'Gıdaların kimyasal buhar, toz veya yüzey kalıntılarıyla kirlenerek ağız yoluyla zehirlenmeye yol açması', ['Yiyecek kokusunun pH kağıtlarının rengini kalıcı biçimde maviye dönüştürmesi', 'İçecek şişelerinin laboratuvar sıcaklığını düşürerek tepkime hızlarını yavaşlatması', 'Ekmek kırıntılarının cam malzemeleri çizerek hacim kalibrasyonunu bozması'], 'Tezgahlar, eldivenler ve laboratuvar havası eser miktarda toksik/kanserojen kimyasal barındırabilir; gıda tüketimi bu maddelerin sindirim yoluyla vücuda girmesine neden olur.'),
  ('Vücudun geniş bir bölümüne korozif kimyasal döküldüğünde veya kıyafet tutuştuğunda kullanılmak üzere tavandan bol su akıtan acil güvenlik donanımı hangisidir?', 'Acil güvenlik (boy) duşu', ['Göz yıkama çeşmesi', 'Yıkama şişesi', 'Geri soğutucu hortumu'], 'Acil boy duşu, kolu çekildiğinde saniyeler içinde yüksek debili su akıtarak tüm vücuttaki kimyasalın hızla seyreltilip uzaklaştırılmasını sağlar.'),
  ('Borosilikat camdan (örneğin Pyrex) üretilen beherglas ve erlenmayerlerin adi pencere camına göre ısıtmaya çok daha dayanıklı olmasının nedeni nedir?', 'Isıl genleşme katsayısının çok düşük olması sayesinde sıcaklık değişimlerinde çatlamaya direnç göstermesi', ['İçeriğinde yüksek oranda kurşun metali bulunması nedeniyle ısıyı hiç iletmemesi', 'Esnek plastik liflerle dokunduğu için düştüğünde bile hiç kırılmaması', 'Yüzeyinin teflon ile kaplı olması sayesinde alevi tamamen geri yansıtması'], 'Borosilikat cam yapısındaki bor trioksit sayesinde düşük ısıl genleşme katsayısına sahiptir; bu özellik ısıtma ve soğutmada termal şok direncini artırır.'),
  ('Karanlıkta veya kahverengi (amber) renkli cam şişelerde saklanan gümüş nitrat (AgNO3) ve hidrojen peroksit (H2O2) gibi maddelerin ortak özelliği nedir?', 'Işık enerjisi etkisiyle fotokimyasal olarak bozunup yapılarının değişmesi', ['Şeffaf camla temas ettiklerinde camı eriterek dışarı sızmaları', 'Yalnızca karanlık ortamda sıvı halde kalıp ışıkta donmaları', 'Güneş ışığı gördüklerinde radyoaktif gama ışınları yaymaları'], 'Amber (koyu kahverengi) şişeler morötesi ve kısa dalga boylu görünür ışığı soğurarak ışığa duyarlı (fotosensitif) kimyasalların bozunmasını engeller.'),
  ('Üç valfli (A, S, E harfli) kauçuk puar kullanılarak pipete sıvı çekilirken valflerin doğru kullanım sırası nasıldır?', 'Önce A valfine basılıp puf sıkılarak hava boşaltılır, sonra S valfine basılarak sıvı çekilir ve E valfiyle boşaltılır', ['Önce S valfine basılıp puar şişirilir, ardından A valfiyle sıvı çekilir ve puar çıkarılarak boşaltılır', 'Her üç valfe aynı anda basılarak sıvının yerçekimine karşı yükselmesi beklenir', 'Önce E valfine basılıp sıvı çekilir, sonra A valfiyle hacim ayarlanıp S valfiyle akıtılır'], 'Üç valfli puarda A (Air) havayı boşaltıp vakum hazırlar, S (Suction) pipete sıvıyı çeker, E (Empty) ise sıvının kontrollü biçimde dışarı akmasını sağlar.'),
  ('Laboratuvarda eldiven kullanımına ilişkin aşağıdaki uygulamalardan hangisi güvenlik kurallarına uygundur?', 'Çalışılan kimyasala uygun eldiven seçmek ve laboratuvardan çıkarken kapı kollarına dokunmadan önce eldiveni çıkarmak', ['Aynı eldivenle deney yaptıktan sonra koridora çıkıp asansör düğmelerine ve cep telefonuna dokunmak', 'Lateks eldivenin her türlü organik çözücüye ve derişik nitrik aside sonsuz süre dayandığını varsaymak', 'Eldiven giyildiği sürece derişik asitlerin içerisine elleri daldırarak cam parçalarını toplamak'], 'Kirli eldivenle ortak yüzeylere (kapı kolu, telefon, kalem) dokunmak çapraz kimyasal bulaşmaya yol açar; ayrıca her eldiven malzemesinin (nitril, neopren, lateks) kimyasal geçirgenliği farklıdır.'),
  ('Cam boruları veya termometreleri delikli kauçuk tıpalara geçirirken camın kırılıp eli kesmesini önlemek için hangi önlem alınmalıdır?', 'Cam boru ve tıpa deliği su veya gliserinle kayganlaştırılmalı, kalın koruyucu eldiven/bezle tıpanın hemen yakınından tutularak hafifçe döndürülmeli', ['Cam boru en uzak ucundan avuç içiyle kavranıp bütün vücut ağırlığıyla kuru tıpaya dik olarak bastırılmalı', 'Tıpa bek alevinde eritildikten sonra soğuk cam boru çekiçle vurularak delikten geçirilmeli', 'Cam boru pense ile sıkılarak itilmeli ve bükülme direnci zorlanarak test edilmeli'], 'Laboratuvardaki en yaygın ağır el kesiklerinden biri kuru tıpaya cam boru zorlamaktır; su/gliserinle yağlama ve tıpaya çok yakın mesafeden havlu/kesilmez eldivenle tutarak çevirerek ilerletme temel kuraldır.'),
  ('Isıtma işlemlerinde sıvıları doğrudan alev yerine en fazla 100 °C\'ye kadar yumuşak ve sabit sıcaklıkta ısıtmak için içinde su kaynatılan metal veya cam kaba ne denir?', 'Su banyosu', ['Kül fırını', 'Desikatör', 'Ayırma hunisi'], 'Su banyosu (benmari), kaynayan suyun sıcaklığı 1 atm\'de 100 °C\'yi aşmadığı için sıcaklığa duyarlı veya düşük kaynama noktalı maddelerin aşırı ısınmadan güvenli ısıtılmasını sağlar.'),
  ('Manyetik karıştırıcı tablası üzerinde çözeltinin kendi kendine dönerek karışmasını sağlayan, teflon kaplı küçük mıknatıs çubuğa ne ad verilir?', 'Manyetik balık', ['Cam baget', 'Porselen kroze', 'Kauçuk puar'], 'Teflon (PTFE) kaplı manyetik balık, kimyasallarla tepkimeye girmeden kabın içinden döner manyetik alanla çözeltiyi homojen biçimde karıştırır.'),
  ('GHS piktogramları hangi geometrik çerçeve ve renk düzeni içinde standart olarak basılır?', 'Kırmızı çerçeveli, beyaz zeminli dik duran kare (eşkenar dörtgen) içinde siyah sembol', ['Mavi daire zemin üzerinde beyaz çizgili sembol', 'Sarı eşkenar üçgen içinde yeşil kenarlıklı sembol', 'Turuncu dikdörtgen zemin üzerinde kırmızı yazılı sembol'], 'Eski turuncu kare sembollerin yerini alan küresel GHS piktogramları, köşesi üzerinde duran kırmızı kenarlıklı beyaz eşkenar dörtgen (karo) içindeki siyah figürlerden oluşur.'),
  ('Sıcak bir beherglas veya erlenmayerin soğuk veya ıslak mermer tezgah üzerine doğrudan konulmayıp ahşap/mantar altlık veya tel kafes üzerine bırakılmasının nedeni nedir?', 'Ani sıcaklık farkından (termal şoktan) dolayı cam tabanın çatlayıp içindeki sıcak sıvının dökülmesini önlemek', ['Mermer tezgahın ısınıp eriyerek cam kabın tabanına yapışmasını engellemek', 'Ahşap altlığın sıcaklığı artırarak çözeltinin kaynamasını sürdürmesini sağlamak', 'Islak tezgahın beherglas içindeki sıvıyı cam gözeneklerinden dışarı çekmesini önlemek'], 'Çok sıcak cam kap soğuk ve ısı iletkenliği yüksek ıslak tezgaha değdiğinde alt yüzey aniden büzülürken iç/üst kısım sıcak kalır; oluşan gerilme cam tabanı patlatabilir.'),
  ('Çözeltilerin yaklaşık asitlik veya bazlık durumunu renk değişimiyle hızlıca kontrol etmek için kullanılan emdirilmiş kağıt şeritlere ne ad verilir?', 'Turnusol veya pH indikatör kağıdı', ['Kromatografi süzgeç kağıdı', 'Parafilm sızdırmazlık bandı', 'Tartım kağıdı'], 'Turnusol kağıdı (asitte kırmızı, bazda mavi) ve üniversal pH kağıtları, çözeltiden baget ucuyla alınan tek bir damlayla pH aralığını pratik olarak gösterir.'),
  ('Katı-sıvı homojen bir karışımdan yalnızca katı bileşeni elde etmek amacıyla sıvının ısıtılarak uzaklaştırılması işlemine ne ad verilir?', 'Buharlaştırma', ['Ayrımsal damıtma', 'Süblimleştirme', 'Santrifüjleme'], 'Katı-sıvı çözeltilerde sıvı bileşen uçurularak katının kapta kalması buharlaştırma ile sağlanır.'),
  ('Tuzlu su gibi katı-sıvı homojen bir karışımdan hem tuzu hem de saf suyu ayrı ayrı elde etmek için hangi ayırma yöntemi kullanılır?', 'Basit damıtma', ['Ayırma hunisiyle ayırma', 'Ayrımsal kristallendirme', 'Süzgeç kâğıdıyla süzme'], 'Basit damıtmada sıvı buharlaştırılıp geri soğutucuda yoğuşturularak her iki bileşen de saf olarak kazanılır.'),
  ('Basit damıtma düzeneğinde kaynama balonundan çıkan sıcak buharın tekrar sıvı faza geçmesini sağlayan cam bölmenin adı nedir?', 'Geri soğutucu', ['Fraksiyon (damıtma) kolonu', 'Büchner süzme hunisi', 'Erlenmayer toplama kabı'], 'Liebig tipi geri soğutucu, dış ceketinden geçen soğuk su yardımıyla buharı yoğuşturur.'),
  ('Damıtma işlemi sonucunda soğutucuda yoğuşarak toplama kabında (erlenmayerde) biriken saf sıvıya ne ad verilir?', 'Destilat (damıtık)', ['Süzüntü (filtrat)', 'Çökelek (tortu)', 'Özüt (ekstrakt)'], 'Damıtma yoluyla buharlaştırılıp tekrar yoğuşturulan sıvı ürüne destilat denir.'),
  ('Ham petrolün benzin, motorin, gaz yağı ve asfalt gibi ticari ürünlere ayrılmasında endüstride kullanılan temel yöntem hangisidir?', 'Ayrımsal damıtma', ['Su buharı damıtması', 'Ayrımsal kristallendirme', 'Süperkritik özütleme'], 'Ham petrol, kaynama noktası aralıkları farklı çok sayıda hidrokarbonun homojen karışımı olduğundan ayrımsal damıtma kulelerinde bileşenlerine ayrılır.'),
  ('Zeytinyağı ve su gibi birbiri içinde çözünmeyen sıvı-sıvı heterojen karışımlara ne ad verilir?', 'Emülsiyon', ['Süspansiyon', 'Aerosol', 'Kolloid'], 'Bir sıvının başka bir sıvı içinde çözünmeden heterojen dağılmasıyla oluşan karışımlara emülsiyon denir.'),
  ('Birbiri içinde çözünmeyen ve özkütleleri birbirinden farklı olan iki sıvıyı laboratuvarda ayırmak için kullanılan musluklu cam gereç hangisidir?', 'Ayırma hunisi', ['Büret', 'Mezür', 'Balon joje'], 'Ayırma hunisi, yoğunlukları farklı ve birbiriyle karışmayan sıvıları faz sınırından musluk yardımıyla ayırmaya yarar.'),
  ('Özkütlesi 0,8 g/cm³ olan zeytinyağı ile özkütlesi 1,0 g/cm³ olan saf su ayırma hunisine konulduğunda musluk açılınca toplama kabına ilk önce hangi sıvı akar?', 'Saf su', ['Zeytinyağı', 'İkisi aynı anda homojen olarak akar', 'Üst fazdaki hafif sıvı önce akar'], 'Özkütlesi büyük olan su (1,0 g/cm³) ayırma hunisinin alt kısmında toplanır ve musluk açıldığında ilk olarak ayrılır.'),
  ('Aşağıdaki sıvı çiftlerinden hangisi ayırma hunisi kullanılarak bileşenlerine ayrılabilir?', 'Benzin ve saf su', ['Etil alkol ve saf su', 'Aseton ve saf su', 'Sirke asidi (asetik asit) ve saf su'], 'Benzin apolar hidrokarbon karışımı, su ise polar yapılı olduğundan birbiri içinde çözünmezler ve ayırma hunisiyle ayrılırlar.'),
  ('Katı bir maddenin sıcak suda tamamen çözülüp çözeltinin soğutulmasıyla katının düzgün geometrik şekilli tanecikler hâlinde tekrar çöktürülmesi işlemine ne ad verilir?', 'Kristallendirme', ['Süblimleştirme', 'Dekantasyon', 'Flotasyon'], 'Çözünürlüğü sıcaklıkla değişen katıların doygun çözeltilerinin soğutularak saf katı kristalleri hâlinde çöktürülmesine kristallendirme denir.'),
  ('Aynı çözücüde çözünen iki veya daha fazla katının çözünürlüklerinin sıcaklıkla farklı oranda değişmesinden yararlanılarak ayrılması yöntemine ne ad verilir?', 'Ayrımsal kristallendirme', ['Ayrımsal damıtma', 'Basit süzme', 'Diyalizle saflaştırma'], 'İki katının aynı çözücüdeki sıcaklık-çözünürlük eğrilerinin farklı olmasına dayanan ayırma tekniği ayrımsal kristallendirmedir.'),
  ('Kum ve yemek tuzu (NaCl) katı karışımından saf yemek tuzu kristalleri elde etmek için sırasıyla uygulanması gereken işlemler dizisi hangisidir?', 'Suda çözme - Süzme - Buharlaştırma/Kristallendirme', ['Süblimleştirme - Ayırma hunisi - Damıtma', 'Mıknatıslama - Eleme - Santrifüjleme', 'Erime noktası farkıyla eritme - Diyaliz - Süzme'], 'Su eklendiğinde tuz çözünür, kum çözünmez; süzmeyle kum ayrılır, süzüntüdeki su buharlaştırılıp kristallendirilerek tuz kazanılır.'),
  ('Bir karışımdaki bileşenlerden yalnızca birini uygun bir çözücü yardımıyla seçici olarak çözüp karışımdan alma işlemine ne ad verilir?', 'Özütleme (ekstraksiyon)', ['Süblimleştirme', 'Santrifüjleme', 'Koagülasyon (pıhtılaştırma)'], 'Katı veya sıvı bir karışımdaki hedef maddenin uygun çözücüye geçirilerek ayrılması işlemine özütleme (ekstraksiyon) denir.'),
  ('Gündelik hayatta kuru çay yapraklarının üzerine sıcak su dökülerek çayın renginin, aromasının ve tein maddesinin suya geçmesi hangi ayırma tekniğine örnektir?', 'Özütleme', ['Ayrımsal damıtma', 'Ayrımsal kristallendirme', 'Basit süzme'], 'Çay yapraklarındaki suda çözünebilen bileşenlerin sıcak su çözücüsüne aktarılması katı-sıvı özütleme işlemidir.'),
  ('Şeker pancarının ince dilimler hâlinde doğranarak sıcak su kazanlarında bekletilmesiyle pancardaki şekerin suya alınması endüstride hangi yöntemin uygulamasıdır?', 'Özütleme', ['Ters osmoz', 'Elektroliz', 'Dekantasyon'], 'Pancar posasındaki sakkarozun su çözücüsü yardımıyla seçici olarak çözülüp alınması özütlemedir.'),
  ('Tuzlu beyaz peynirin veya salamura zeytinin yemeden önce bir süre su içinde bekletilerek fazla tuzunun giderilmesi hangi ayırma prensibine dayanır?', 'Çözünürlük farkına dayalı özütleme', ['Kaynama noktası farkına dayalı damıtma', 'Yoğunluk farkına dayalı yüzdürme', 'Tanecik boyutu farkına dayalı eleme'], 'Peynir veya zeytindeki tuzun su fazına geçerek uzaklaştırılması çözünürlük farkıyla yapılan özütlemedir.'),
  ('Birbiri içinde tamamen çözünen iki sıvıdan oluşan homojen karışımlara kimyada genel olarak ne ad verilir?', 'Sıvı-sıvı çözelti', ['Emülsiyon', 'Süspansiyon', 'Kolloid'], 'Homojen tüm karışımlar çözelti olarak adlandırılır; alkol-su gibi sıvı-sıvı homojen karışımlar sıvı-sıvı çözeltidir.'),
  ('Tuz göllerinden yaz aylarında güneş ısısı yardımıyla yemek tuzu üretilmesi hangi doğal fiziksel ayırma sürecine dayanır?', 'Buharlaştırma ile kristallendirme', ['Ayrımsal damıtma', 'Santrifüjleme', 'Diyaliz'], 'Güneş enerjisiyle göl suyu buharlaştıkça tuz derişimi doygunluk sınırını aşar ve tuz kristalleri çöker.'),
  ('Katı-sıvı çözeltilerde kaynama noktasının saf çözücüye göre daha yüksek olmasının basit damıtma sırasındaki sonucu nedir?', 'Tuzlu su damıtılırken kaynama sıcaklığının 100 °C\'nin üzerinde başlaması ve zamanla artması', ['Tuzlu suyun 1 atm basınçta sabit 78 °C sıcaklıkta kaynayarak tamamen buharlaşması', 'Su buharlaştıkça çözeltinin kaynama sıcaklığının giderek 0 °C\'ye doğru düşmesi', 'Tuzun sudan daha önce buharlaşarak geri soğutucuda kristallenmesi'], 'Uçucu olmayan katı çözündüğünde kaynama noktası yükselir; su buharlaştıkça çözelti derişimi arttığından doygunluğa ulaşana dek sıcaklık yükselir.'),
  ('Parfüm ve kolonya üretiminde etil alkol, su ve esans yağlarının homojen karışımından alkolün geri kazanılmasında yararlanılan fiziksel özellik farkı hangisidir?', 'Kaynama noktası farkı', ['Tanecik boyutu farkı', 'Manyetik duyarlılık farkı', 'Elektriklenme farkı'], 'Homojen sıvı-sıvı karışımlarında uçucu bileşenlerin ayrılması kaynama noktası (uçuculuk) farkına dayanır.'),
  ('Sabit basınçta saf bir sıvı damıtılırken sıvının tamamı buharlaşana kadar geçen sürede termometrede okunan değer nasıl değişir?', 'Sabit kalır', ['Sürekli ve doğrusal olarak artar', 'Önce hızla artar, sonra sıfıra düşer', 'Kabın hacmiyle ters orantılı olarak azalır'], 'Saf maddelerin sabit dış basınç altında hâl değişimi (kaynama) süresince sıcaklıkları sabit kalır.'),
  ('Şekerli su çözeltisinden yalnızca katı şekeri elde etmek isteyen bir aşçı, yüksek ısıda şekerin karamelize olup yanmaması için suyu düşük basınçlı kazanda uçuruyor. Bu işlem temel olarak hangi yöntemin kontrollü uygulamasıdır?', 'Vakum altında buharlaştırma', ['Ayırma hunisiyle faz ayırma', 'Kâğıt kromatografisiyle sürükleme', 'Mıknatıslama ile ayırma'], 'Sıvı çözücünün düşük basınçta kaynatılarak uçurulması ve katının kazanılması vakumlu buharlaştırma (evaporasyon) işlemidir.'),
  ('Katı bir maddenin ısıtıldığında sıvı faza geçmeden doğrudan gaz fazına geçmesi olayına ne ad verilir?', 'Süblimleşme', ['Kırağılaşma', 'Yoğuşma', 'Kristallenme'], 'Katı maddelerin erimeden doğrudan buhar fazına dönüşmesine süblimleşme denir.'),
  ('Oda koşullarında veya hafif ısıtıldığında kolayca süblimleşebilen katılara örnek olarak aşağıdakilerden hangisi verilebilir?', 'Naftalin ve iyot katısı', ['Yemek tuzu (NaCl) ve kum', 'Kalsiyum karbonat ve demir tozu', 'Çay şekeri ve sodyum sülfat'], 'Naftalin, iyot (I₂), kuru buz (katı CO₂) ve amonyum klorür (NH₄Cl) süblimleşebilen başlıca katılardır.'),
  ('Kolloidal karışımlardaki veya biyolojik sıvılardaki küçük iyon ve metabolik atık moleküllerin yarı geçirgen bir zar (membran) aracılığıyla büyük taneciklerden ayrılması yöntemine ne ad verilir?', 'Diyaliz', ['Santrifüjleme', 'Koagülasyon', 'Flotasyon'], 'Yarı geçirgen zarın gözeneklerinden yalnız küçük iyon ve moleküllerin geçebilmesine dayanan ayırma tekniği diyalizdir.'),
  ('Böbrek yetmezliği olan hastalarda kanda biriken üre, kreatinin ve fazla iyonların temizlenmesini sağlayan hemodiyaliz cihazı hangi fiziksel özellik farkına dayanarak çalışır?', 'Tanecik boyutu farkı', ['Kaynama noktası farkı', 'Manyetik özellik farkı', 'Erime noktası farkı'], 'Hemodiyaliz zarındaki gözenekler üre ve küçük iyonların geçişine izin verirken kan hücreleri ve büyük proteinlerin geçişini tanecik boyutu farkıyla engeller.'),
  ('Süzgeç kâğıdından geçebilecek kadar küçük veya çökmesi çok uzun süren asılı tanecikleri içeren karışımları yüksek hızda döndürerek merkezkaç etkisiyle çöktürme yöntemine ne ad verilir?', 'Santrifüjleme', ['Dekantasyon', 'Süblimleştirme', 'Ekstraksiyon'], 'Merkezkaç kuvveti yardımıyla yoğunluğu fazla olan asılı taneciklerin tüpün dibine hızla çöktürülmesi işlemine santrifüjleme denir.'),
  ('Tıbbi tahlil laboratuvarlarında tüpe alınan tam kan örneğinin birkaç dakika içinde altta kan hücreleri (alyuvar, akyuvar), üstte ise sarımsı kan plazması (veya serum) olacak şekilde ayrılması hangi cihazla sağlanır?', 'Santrifüj cihazı', ['Basit damıtma düzeneği', 'Soxhlet ekstraktörü', 'Ayırma hunisi'], 'Kan bir kolloid/süspansiyon karışımıdır; santrifüj cihazında yüksek devirde döndürüldüğünde yoğun kan hücreleri dibe çöker, üstte plazma kalır.'),
  ('Katı-sıvı heterojen bir karışımın (süspansiyonun) gözenekli bir süzgeç kâğıdı veya filtreden geçirilerek katının süzgeçte tutulması işlemine ne ad verilir?', 'Süzme (filtrasyon)', ['Damıtma (destilasyon)', 'Özütleme (ekstraksiyon)', 'Kromatografi'], 'Süspansiyonlardaki çözünmeyen katı taneciklerin tanecik boyutu farkıyla sıvıdan ayrılması süzme işlemidir.'),
  ('Süzme işleminde süzgeç kâğıdının gözeneklerinden geçerek toplama kabında (erlenmayer veya beherde) biriken sıvı kısma ne ad verilir?', 'Süzüntü (filtrat)', ['Destilat (damıtık)', 'Çökelek (rezidü)', 'Elüent (yürütücü)'], 'Süzgeçten geçen sıvı faza süzüntü (filtrat), süzgeç kâğıdı üzerinde kalan katıya ise çökelek veya kalıntı (rezidü) denir.'),
  ('Otomobillerdeki hava filtresinin, elektrikli süpürge toz torbasının ve fabrika bacalarındaki toz tutucu filtrelerin çalışma prensibi hangi karışım türünü hangi özellikle ayırmaya dayanır?', 'Katı-gaz heterojen karışımları (katı aerosolleri) tanecik boyutu farkıyla süzmeye', ['Gaz-gaz homojen karışımları kaynama noktası farkıyla damıtmaya', 'Sıvı-sıvı emülsiyonları özkütle farkıyla ayırma hunisinden geçirmeye', 'Katı-katı alaşımları erime noktası farkıyla saflaştırmaya'], 'Havadaki toz ve duman gibi katı-gaz heterojen karışımların gözenekli filtrelerden geçirilerek tutulması gazlarda süzme işlemidir.'),
  ('Aşağıdaki karışımlardan hangisi laboratuvarda süzgeç kâğıdı kullanılarak bileşenlerine ayrılamaz?', 'Şekerli su çözeltisi', ['Tebeşir tozu - su karışımı', 'Kum - su karışımı', 'Naftalin - su karışımı'], 'Şekerli su homojen bir çözeltidir; çözünmüş şeker molekülleri süzgeç kâğıdının gözeneklerinden suyla birlikte geçer ve süzmeyle ayrılamaz.'),
  ('Bir karışımdaki bileşenlerin sabit bir faz üzerinde hareketli bir faz (çözücü) yardımıyla farklı hızlarda sürüklenerek ayrılmasına dayanan analitik yönteme ne ad verilir?', 'Kromatografi', ['Kristallendirme', 'Santrifüjleme', 'Diyaliz'], 'Sabit faz ile hareketli faz arasındaki tutunma (adsorpsiyon) ve çözünme (dağılma) farkına dayanan ayırma tekniği kromatografidir.'),
  ('Siyah keçeli kalem mürekkebinin süzgeç kâğıdına damlatılıp kâğıdın alt ucu suya veya alkole değdirildiğinde farklı renkli halkalara/lekelere ayrılması hangi tekniğin basit bir uygulamasıdır?', 'Kâğıt kromatografisi', ['Ayrımsal damıtma', 'Sıvı-sıvı özütleme', 'Süblimleştirme'], 'Mürekkep içindeki farklı boya pigmentlerinin selüloz kâğıt (sabit faz) üzerinde çözücü (hareketli faz) ile farklı hızlarda ilerlemesi kâğıt kromatografisidir.'),
  ('Bir ince tabaka kromatografisi deneyinde başlangıç çizgisinden itibaren çözücü cephesi 8,0 cm yükseldiğinde A maddesinin lekesi başlangıç çizgisinden 6,0 cm yukarıda ölçülmüştür. A maddesinin Rf değeri kaçtır?', '0,75', ['1,33', '0,25', '0,60'], 'Rf = (Maddenin aldığı yol) / (Çözücünün aldığı yol) = 6,0 cm / 8,0 cm = 0,75 olarak bulunur.'),
  ('Ispanak yaprakları havanda asetonla ezilerek yeşil yaprak özütü elde ediliyor, posası süzgeçten geçiriliyor ve yeşil sıvı kâğıt üzerinde klorofil-a, klorofil-b ve karotenoid bantlarına ayrılıyor. Bu deneyde sırasıyla hangi üç ayırma yöntemi uygulanmıştır?', 'Özütleme - Süzme - Kâğıt kromatografisi', ['Damıtma - Ayırma hunisi - Kristallendirme', 'Süblimleştirme - Santrifüjleme - Diyaliz', 'Mıknatıslama - Yüzdürme - Basit buharlaştırma'], 'Asetonla pigmentlerin yapraktan çekilmesi özütleme, yaprak posasının ayrılması süzme, pigmentlerin kâğıt üzerinde renkli bantlara ayrılması kâğıt kromatografisidir.'),
  ('Talaş ve kum gibi her ikisi de suda çözünmeyen ancak birinin özkütlesi sudan küçük, diğerininki sudan büyük olan katı-katı karışımlarını suya atarak yüzeyden toplama yöntemine ne ad verilir?', 'Yüzdürme (flotasyon)', ['Özütleme (ekstraksiyon)', 'Ayrımsal kristallendirme', 'Süblimleştirme'], 'Özkütlesi sıvıdan küçük katının sıvı yüzeyine çıkması, büyük olanın dibe batmasıyla yapılan ayırma işlemi yüzdürme (flotasyon) yöntemidir.'),
  ('Demir (Fe), nikel (Ni) ve kobalt (Co) metallerinden birini içeren heterojen katı bir karışıma mıknatıs yaklaştırıldığında ayırmanın gerçekleşebilmesi için en önemli şart nedir?', 'Diğer bileşenin mıknatıstan etkilenmeyen bir madde olması ve metallerin alaşım yapmamış olması', ['Karışımdaki maddelerin homojen bir sıvı çözelti hâlinde bulunması', 'Her iki metalin de ferromanyetik olup eşit şiddetle mıknatısa yapışması', 'Karışımın erime noktasının üzerine kadar ısıtılarak sıvılaştırılması'], 'Mıknatıs yalnızca Fe, Ni, Co metallerini çeker; bunların birbirleriyle yaptığı karışımlar veya homojen alaşımlar (ör. çelik, lehim) mıknatısla bileşenlerine ayrılamaz.'),
  ('İnşaatlarda çakıl taşlarının ince kumdan ayrılması veya mutfakta unun içindeki topakların giderilmesi hangi basit ayırma yöntemine örnektir?', 'Eleme', ['Süzme', 'Savurma', 'Yüzdürme'], 'Katı-katı heterojen karışımların tanecik boyutu farkından yararlanılarak gözenekli eleklerle ayrılmasına eleme denir.'),
  ('Harman yerinde buğday taneleri ile samanın rüzgâr yardımıyla birbirinden ayrılması geleneksel olarak hangi ayırma yöntemidir?', 'Savurma', ['Eleme', 'Ayıklama', 'Dekantasyon'], 'Özkütleleri farklı iki katıdan hafif olanın (saman) hava akımıyla uzağa taşınması, ağır olanın (buğday) yakına düşmesi savurma yöntemidir.'),
  ('Fabrika bacalarından çıkan dumanın içindeki yüklü kül ve kurum taneciklerinin yüksek voltajlı plakalar arasından geçirilerek tutulması hangi çevre koruma ve ayırma tekniğidir?', 'Elektrostatik çöktürme', ['Ayrımsal damıtma', 'Sıvı-sıvı ekstraksiyon', 'Ayrımsal kristallendirme'], 'Elektrofiltreler, baca gazındaki katı partikülleri elektrik yüküyle yükleyip zıt yüklü levhalarda toplayarak havayı temizler.'),
  ('Çamaşır makinesinin sıkma programında ıslak çamaşırlardaki suyun delikli tamburun yüksek devirde dönmesiyle çamaşırdan uzaklaştırılması hangi iki fiziksel ayırma etkisini bir arada kullanır?', 'Santrifüjleme (merkezkaç kuvveti) ve süzme', ['Basit damıtma ve kristallendirme', 'Özütleme ve kâğıt kromatografisi', 'Süblimleştirme ve mıknatıslama'], 'Yüksek hızda dönen tambur merkezkaç kuvvetiyle (santrifüj etkisi) suyu dışa savurur; delikli tambur ise çamaşırı içeride tutup suyun geçişine izin verir (süzme etkisi).'),
  ('Bir ince tabaka kromatografisi deneyinde başlangıç çizgisinden itibaren çözücü 10,0 cm yükselmiş, X maddesi 4,0 cm ve Y maddesi 4,0 cm yükselmiştir. Yalnızca bu tek deney sonucuna bakılarak X ve Y maddeleri için yapılacak en ihtiyatlı bilimsel yorum nedir?', 'Aynı madde olabilirler; ancak kesin yargı için farklı çözücü sistemlerinde de aynı Rf değerini verip vermedikleri kontrol edilmelidir', ['Atom numaraları ve nötron sayıları kesinlikle farklı iki izotop elementtir', 'X maddesi kesinlikle katı bir metal, Y maddesi ise asal bir gazdır', 'Rf değerleri eşit olduğu için kaynama noktaları arasında en az 100 °C fark vardır'], 'İki farklı madde tesadüfen tek bir çözücüde aynı Rf değerine (0,40) sahip olabilir; farklı polaritedeki çözücülerde de aynı Rf gözlenirse aynı madde olma olasılığı güçlenir.'),
  ('Karışımları ayırma yöntemlerinin tamamı (damıtma, süzme, özütleme, kristallendirme, diyaliz, kromatografi vb.) maddelerin yapısında nasıl bir değişim meydana getirir?', 'Bileşenlerin kimyasal kimliğini değiştirmeden yalnızca fiziksel özellik farklarıyla ayırma sağlar', ['Bileşenlerin kovalent ve iyonik bağlarını kopararak yeni elementler oluşturur', 'Atom çekirdeklerindeki proton sayılarını değiştirerek radyoaktif dönüşüm yapar', 'Karışımdaki tüm maddeleri tek bir yeni kimyasal bileşiğe dönüştürür'], 'Karışımlar fiziksel yollarla oluşur ve yine bileşenlerin kimyasal yapısı korunarak fiziksel ayırma yöntemleriyle bileşenlerine ayrılır.'),
  ('Çamurlu suyun bir süre dinlendirilmesiyle kaba çamurun kabın dibine çökmesi olayına ne ad verilir?', 'Çöktürme', ['Süblimleştirme', 'Ayrımsal damıtma', 'Kromatografi'], 'Askıdaki katı taneciklerin yer çekimi etkisiyle zamanla kabın dibinde toplanmasına çöktürme (sedimentasyon) denir.'),
  ('Asit-baz titrasyonlarında asitten gelen H⁺ mol sayısının bazdan gelen OH⁻ mol sayısına tam eşitlendiği teorik noktaya ne ad verilir?', 'Eşdeğerlik noktası', ['Tamponlama kapasitesi sınırı', 'İndikatör bozunma basamağı', 'Çözünürlük çarpımı dengesi'], 'Asidin ve bazın stokiyometrik olarak birbirini tam tükettiği kuramsal nokta eşdeğerlik noktasıdır.'),
  ('Titrasyon sırasında eklenen indikatörün gözle görülür kalıcı renk değiştirdiği deneysel ana ne ad verilir?', 'Dönüm noktası', ['Nötralleşme başlangıcı', 'Hidroliz denge noktası', 'İyonlaşma sınırı noktası'], 'İndikatörün çözeltide kalıcı renk değiştirerek titrasyonun sonlandırıldığını gösterdiği deneysel an dönüm noktasıdır.'),
  ('Fenolftalein indikatörü asidik bir sulu çözeltiye damlatıldığında çözeltinin görünümü nasıl olur?', 'Renksiz', ['Parlak pembe', 'Koyu mavi', 'Turuncu kırmızı'], 'Fenolftalein asidik ve nötr ortamlarda (pH yaklaşık 8,2 değerinin altında) renksizdir.'),
  ('Bazik bir sulu çözeltiye birkaç damla fenolftalein damlatıldığında gözlenen karakteristik renk aşağıdakilerden hangisidir?', 'Pembe - fuşya', ['Parlak sarı', 'Kiremit kırmızısı', 'Zümrüt yeşili'], 'Fenolftalein pH yaklaşık 8,2 - 10,0 aralığının üzerindeki bazik ortamlarda pembe-fuşya renk alır.'),
  ('Metil oranj indikatörü kuvvetli asidik (pH < 3,1) bir çözeltiye damlatıldığında hangi rengi alır?', 'Kırmızı', ['Parlak sarı', 'Menekşe moru', 'Çivit mavisi'], 'Metil oranj pH 3,1 değerinin altındaki kuvvetli asidik ortamlarda kırmızı renk verir.'),
  ('Metil oranj indikatörünün bazik bir sulu çözeltide oluşturduğu renk aşağıdakilerden hangisidir?', 'Sarı', ['Fuşya pembe', 'Koyu lacivert', 'Zümrüt yeşili'], 'Metil oranj pH 4,4 değerinin üzerindeki zayıf asidik, nötr ve bazik ortamlarda sarı renktedir.'),
  ('Mavi turnusol kâğıdı seyreltik hidroklorik asit (HCl) çözeltisine batırıldığında hangi renge dönüşür?', 'Kırmızı', ['Turuncu sarı', 'Parlak yeşil', 'Renksiz beyaz'], 'Asidik çözeltiler mavi turnusol kâğıdının rengini kırmızıya çevirir.'),
  ('Kırmızı turnusol kâğıdı sodyum hidroksit (NaOH) sulu çözeltisine daldırıldığında rengi ne olur?', 'Mavi', ['Parlak sarı', 'Açık turuncu', 'Menekşe moru'], 'Bazik çözeltiler kırmızı turnusol kâğıdının rengini maviye dönüştürür.'),
  ('Titrasyon düzeneğinde büretin altına yerleştirilen, çalkalama sırasında sıvı sıçramasını önleyen dar boyunlu konik cam kap hangisidir?', 'Erlenmayer', ['Beherglas', 'Dereceli silindir', 'Büchner hunisi'], 'Konik gövdesi ve dar boynu sayesinde çalkalamaya en elverişli titrasyon kabı erlenmayerdir.'),
  ('Saf suya (25 °C, pH = 7) kırmızı ve mavi turnusol kâğıtları ayrı ayrı batırıldığında kâğıtların renklerinde nasıl bir değişim gözlenir?', 'Her iki kâğıdın rengi de değişmez', ['İkisi de menekşe moruna dönüşür', 'Kırmızı maviye, mavi kırmızıya döner', 'Her iki kâğıt da tamamen ağararak beyazlaşır'], 'Nötr ortamda kırmızı turnusol kırmızı, mavi turnusol mavi olarak kalır.'),
  ('Kırmızı lahana suyu damlatılmış taze limon suyunda gözlenen renk aşağıdakilerden hangisidir?', 'Kırmızı - pembe', ['Koyu mavi', 'Açık yeşil', 'Parlak sarı'], 'Limon suyu sitrik asit içerdiğinden asidiktir ve antosiyanin içeren lahana suyunu kırmızı-pembe renge çevirir.'),
  ('Evrensel (üniversal) indikatör kâğıdının tek bir indikatöre göre sağladığı en önemli üstünlük aşağıdakilerden hangisidir?', 'Birçok indikatörün karışımını içerdiği için geniş pH aralığında farklı renklerle yaklaşık pH değerini göstermesi', ['Yalnızca kuvvetli bazların bulunduğu çözeltilerde tek bir renge dönüşerek diğer tüm pH bölgelerinde renksiz kalması', 'Çözeltinin pH değerini virgülden sonra dört basamak hassasiyetle dijital olarak ekrana yansıtabilmesi', 'Suda hiç ıslanmadan kap dışından kızılötesi ışıma yoluyla asidin mol kütlesini hesaplaması'], 'Üniversal indikatör, farklı pH aralıklarında renk değiştiren boyaların karışımıdır ve tüm pH skalası boyunca renk skalasıyla yaklaşık pH\'ı verir.'),
  ('Alizarin sarısı indikatörü pH 10,1 altında sarı, pH 12,0 üzerinde kırmızı renktedir; bu indikatör hangi tür çözeltileri ayırt etmekte kullanılır?', 'Kuvvetli bazik çözeltileri orta bazik ve nötr çözeltilerden ayırt etmekte', ['Kuvvetli asidik çözeltileri zayıf asidik çözeltilerden ayırt etmekte', 'Saf suyu seyreltik yemek tuzu (NaCl) çözeltisinden ayırt etmekte', 'Asidik tampon çözeltilerin pH 3 ile pH 5 arasındaki geçişini izlemekte'], 'Renk değişim aralığı pH 10,1 - 12,0 olduğundan yüksek pH\'lı kuvvetli bazik ortamların tespitinde kullanılır.'),
  ('Titrasyonda erlenmayere konulan ve derişimi belirlenmek istenen çözeltiye analitik kimyada ne ad verilir?', 'Analit', ['Standart titrant çözeltisi', 'İndikatör tamponu', 'Katalitik çözücü faz'], 'Derişimi veya miktarı tayin edilmek istenen madde veya çözeltiye analit denir.'),
  ('Turnusol boyası doğal olarak aşağıdaki canlı gruplarından hangisinden elde edilen bir karışımdır?', 'Likenlerden', ['Deniz süngerlerinden', 'İğne yapraklı çamlardan', 'Toprak solucanlarından'], 'Turnusol (litmus), özellikle Roccella tinctoria gibi çeşitli liken türlerinden özütlenen suda çözünür doğal boya karışımıdır.'),
  ('Titrasyon sırasında erlenmayerin altına beyaz bir kâğıt veya porselen plaka konulmasının pratik amacı aşağıdakilerden hangisidir?', 'İndikatörün ilk kalıcı soluk renk değişimini arka plan kontrastıyla çok daha net fark edebilmek', ['Erlenmayerin laboratuvar tezgâhından ısı alarak çözeltiyi kaynatmasını engellemek', 'Ortam ışığını tamamen soğurarak çözeltinin fotokimyasal bozunmasını durdurmak', 'Büretten damlayan baz damlalarının hacmini elektrostatik çekimle küçültmek'], 'Beyaz zemin, özellikle fenolftaleinin uçuk pembe veya metil oranjın turuncu renk geçişini ilk damlada görmeyi kolaylaştırır.'),
  ('Timolftalein indikatörü asidik ve nötr ortamda renksiz olup pH 9,3 - 10,5 aralığının üzerindeki bazik çözeltilerde hangi rengi alır?', 'Mavi', ['Kiremit kırmızısı', 'Parlak sarı', 'Koyu yeşil'], 'Timolftalein, fenolftaleine benzer şekilde asitte renksizdir ancak bazik ortamda pembe yerine mavi renk verir.'),
  ('Laboratuvarda bir asit çözeltisinden belirli ve sabit bir hacmi (örneğin tam 25,00 mL) erlenmayere en yüksek doğrulukla aktarmak için hangi cam malzeme kullanılır?', 'Bullu (tam) pipet', ['Beherglas', 'Geniş ağızlı kavanoz', 'Porselen kroze'], 'Sabit bir hacmi çok yüksek hassasiyetle ölçüp aktarmak için tek çizgili bullu (volümetrik) pipet kullanılır.'),
  ('Kuru turnusol kâğıdına kuru amonyak (NH₃) gazı tutulduğunda renk değişimi gözlenmemesinin temel nedeni nedir?', 'NH₃ gazının OH⁻ iyonu oluşturabilmesi için su (nem) ile tepkimeye girmesinin gerekmesi', ['Amonyak gazının gerçekte kuvvetli asidik bir oksit yapısında bulunması', 'Turnusol kâğıdının yalnızca sıvı cıva varlığında kimyasal tepkime vermesi', 'Kuru gazların oda sıcaklığında selüloz yüzeye hiçbir şekilde temas edememesi'], 'Asitlik ve bazlık sulu ortamda iyonlaşmayla gözlenir; kuru kırmızı turnusol kâğıdı ıslatıldığında NH₃ suda çözünüp OH⁻ üretir ve kâğıdı maviye çevirir.'),
  ('Toprak pH değerine göre çiçek rengi değişen ortanca (Hydrangea) bitkisinin asidik topraklarda mavi, bazik topraklarda pembe çiçek açması kimyadaki hangi kavramın doğal bir örneğidir?', 'Doğal indikatör davranışı', ['Radyoaktif yarılanma olayı', 'Ayrımsal damıtma işlemi', 'Elektrolitik kaplama yöntemi'], 'Ortanca çiçeğindeki pigmentler topraktaki pH ve alüminyum iyonu etkileşimine göre renk değiştirerek doğal indikatör gibi davranır.'),
  ('pH kâğıdı ile bir çözeltinin pH ölçümü yapılırken doğru uygulama yöntemi aşağıdakilerden hangisidir?', 'Temiz bir bagetle çözeltiden alınan bir damlayı pH kâğıdına damlatıp renk skalasıyla karşılaştırmak', ['Tüm pH kâğıdı kutusunu ana stok çözelti şişesinin içine atıp bir saat bekletmek', 'pH kâğıdını önce bunzen beki alevinde yakıp küllerini çözeltiye karıştırmak', 'Kâğıdı önce derişik sülfürik aside batırıp ardından test edilecek çözeltiye daldırmak'], 'Stok çözeltiyi kirletmemek için temiz cam baget ucuyla alınan damla pH şeridine değdirilir ve hemen kutudaki renk skalasıyla eşleştirilir.'),
  ('Alev deneyinde sodyum (Na⁺) iyonu içeren bir tuz bunzen beki alevine tutulduğunda alevi hangi karakteristik renge boyar?', 'Parlak altın sarısı', ['Açık menekşe moru', 'Mavi - zümrüt yeşili', 'Koyu tuğla kırmızısı'], 'Sodyum katyonu (Na⁺) alev deneyinde 589 nm civarındaki D-hattı emisyonuyla çok baskın ve parlak sarı renk verir.'),
  ('Potasyum (K⁺) iyonu içeren potasyum klorür (KCl) tuzu temiz bir platin telle aleve tutulduğunda hangi alev rengi gözlenir?', 'Menekşe', ['Parlak altın sarısı', 'Kiremit kırmızısı', 'Elma yeşili'], 'Potasyum (K⁺) iyonları bunzen beki alevinin yükseltgen bölgesinde karakteristik soluk menekşe (leylak) rengi oluşturur.'),
  ('Bakır(II) (Cu²⁺) bileşikleri alev deneyine tabi tutulduğunda alevde gözlenen karakteristik renk aşağıdakilerden hangisidir?', 'Mavi - yeşil', ['Altın sarısı', 'Açık leylak', 'Turuncu sarı'], 'Bakır(II) tuzları (örneğin CuCl₂ veya CuSO₄) alev deneyinde karakteristik mavi-yeşil (turkuaz/zümrüt) emisyon rengi verir.'),
  ('Kalsiyum (Ca²⁺) katyonu içeren bir tuzun bunzen beki alevinde oluşturduğu renk aşağıdakilerden hangisidir?', 'Tuğla kırmızısı', ['Açık menekşe moru', 'Çivit mavisi', 'Soluk elma yeşili'], 'Kalsiyum (Ca²⁺) bileşikleri alev deneyinde turuncuya çalan karakteristik tuğla kırmızısı (kiremit kırmızısı) renk verir.'),
  ('Baryum (Ba²⁺) iyonu içeren baryum klorür (BaCl₂) tuzunun alev deneyinde verdiği karakteristik renk hangisidir?', 'Açık yeşil', ['Koyu menekşe moru', 'Parlak altın sarısı', 'Lal kırmızısı'], 'Baryum (Ba²⁺) iyonları alev deneyinde karakteristik soluk sarı-yeşil (elma yeşili) ışıma yayar.'),
  ('Renksiz ve kokusuz bir gaz olan karbondioksit (CO₂) gazını laboratuvarda nitel olarak tanımak için kullanılan en yaygın ayıraç hangisidir?', 'Berrak kireç suyu — Ca(OH)₂ sulu çözeltisi', ['Saf etil alkol — C₂H₅OH sıvısı', 'Sıvı hekzan — C₆H₁₄ organik çözücüsü', 'Derişik sodyum klorür — NaCl tuzlu suyu'], 'CO₂ gazı berrak kireç suyundan (Ca(OH)₂) geçirildiğinde suda çözünmeyen beyaz CaCO₃ çökeleği oluşturarak çözeltiyi bulandırır.'),
  ('Deney tüpünde toplanan hidrojen (H₂) gazının varlığını doğrulamak için tüp ağzına yanan bir kibrit veya çıra yaklaştırıldığında ne gözlenir?', '"Pop" sesiyle küçük ve karakteristik bir patlama', ['Alevin hiçbir ses çıkarmadan sönmesi ve beyaz çökelek oluşması', 'Kireç suyunun süt beyazı rengine dönüşerek bulanması', 'Tüp içinde keskin kokulu kahverengi gaz bulutu belirmesi'], 'Hidrojen yanıcı bir gazdır; havadaki oksijenle 2H₂ + O₂ → 2H₂O tepkimesini hızla vererek karakteristik ıslık/pop sesiyle patlar.'),
  ('İçinde saf oksijen (O₂) gazı bulunan bir deney tüpüne alevsiz kor halindeki (kıvılcımlı) bir tahta kıymığı daldırıldığında hangi olay gözlenir?', 'Kor halindeki kıymığın yeniden alev alarak parlak biçimde yanması', ['Kıymığın üzerindeki közün anında kararıp buz tutması', 'Tüp ağzında patlama sesiyle birlikte mor duman çıkması', 'Tahta kıymığının eriyerek mavi renkli bir sıvıya dönüşmesi'], 'Oksijen yakıcı bir gazdır; havadaki %21 O₂\'de sadece köz halinde duran çıra, saf O₂ içinde hızlanan yanmayla parlayıp yeniden tutuşur.'),
  ('Havai fişek üretiminde gökyüzünde yeşil, sarı ve mavi-yeşil ışık efektleri elde etmek için sırasıyla hangi metallerin tuzlarından yararlanılır?', 'Baryum (yeşil), sodyum (sarı), bakır (mavi-yeşil)', ['Sodyum (yeşil), potasyum (sarı), kalsiyum (mavi-yeşil)', 'Kalsiyum (yeşil), bakır (sarı), baryum (mavi-yeşil)', 'Potasyum (yeşil), baryum (sarı), sodyum (mavi-yeşil)'], 'Piroteknikte alev emisyon renkleri doğrudan kullanılır: Ba²⁺ yeşil, Na⁺ parlak sarı, Cu²⁺ mavi-yeşil ışık verir.'),
  ('Sokak aydınlatmalarında kullanılan düşük basınçlı sodyum buharlı lambaların sisli havalarda tercih edilen karakteristik ışık rengi hangisidir?', 'Sarı', ['Menekşe moru', 'Zümrüt yeşili', 'Çivit mavisi'], 'Uyarılmış sodyum buharı tıpkı alev deneyindeki gibi yaklaşık 589 nm dalga boyunda monokromatik sarı ışık yayar.'),
  ('Potasyum klorat (KClO₃) katısı bir deney tüpünde ısıtıldığında bozunarak KCl katısı ve bir gaz oluşturur; tüpteki katı kalıntının alev rengi ve çıkan gazın testi hangi seçenekte doğru verilmiştir?', 'Katı kalıntı menekşe alev verir; çıkan gaz kor halindeki çırayı parlatır (O₂)', ['Katı kalıntı sarı alev verir; çıkan gaz kireç suyunu bulandırır (CO₂)', 'Katı kalıntı yeşil alev verir; çıkan gaz "pop" sesiyle patlar (H₂)', 'Katı kalıntı tuğla kırmızısı alev verir; çıkan gaz turnusolu ağartır (Cl₂)'], '2KClO₃(k) → 2KCl(k) + 3O₂(g); oluşan KCl tuzu K⁺ nedeniyle menekşe alev verir, çıkan O₂ gazı ise kor çırayı alevlendirir.'),
  ('İnsan nefesi bir pipet yardımıyla berrak kireç suyunun (Ca(OH)₂) içine üflendiğinde sıvının zamanla bulanmasının nedeni nedir?', 'Soluk verme havasında bulunan CO₂ gazının Ca(OH)₂ ile beyaz CaCO₃ çökeleği oluşturması', ['Nefesteki azot gazının suyla birleşerek amonyak kristalleri meydana getirmesi', 'Nefesteki oksijen gazının kalsiyum iyonlarını yakarak siyah kül oluşturması', 'Ağızdan gelen su buharının kireç suyunu dondurarak buz kristallerine çevirmesi'], 'Hücresel solunum ürünü olan CO₂ gazı soluk havasıyla kireç suyuna geçer ve CaCO₃ oluşturarak çözeltiyi bulandırır.'),
  ('Yangın söndürücü tüplerde karbondioksit (CO₂) gazının kullanılmasını sağlayan iki temel fiziksel ve kimyasal özellik hangisidir?', 'Yanmaması (yakıcı olmaması) ve havadan ağır olduğu için alevin üzerini örterek oksijen temasını kesmesi', ['Çok yanıcı olması ve yanan maddenin sıcaklığını artırarak külü buharlaştırması', 'Havadaki azotla birleşerek "pop" sesiyle patlaması ve rüzgâr oluşturması', 'Havadan çok hafif olması nedeniyle hızla stratosfere yükselip ısıyı taşıması'], 'CO₂(g) mol kütlesi (44 g/mol) havadan (~29 g/mol) büyüktür ve yanmaz; yanan yüzeyin üzerine çökerek O₂ ile teması keser.'),
  ('Nitel analizde "katyon" ve "anyon" terimleri sırasıyla hangi yüklü tanecikleri ifade eder?', 'Katyon pozitif (+) yüklü iyonu, anyon negatif (-) yüklü iyonu ifade eder', ['Katyon negatif (-) yüklü iyonu, anyon pozitif (+) yüklü iyonu ifade eder', 'Katyon yüksüz atom çekirdeğini, anyon serbest nötron taneciğini ifade eder', 'Katyon gaz fazındaki molekülü, anyon katı fazdaki alaşımı ifade eder'], 'Alev deneyinde karakteristik renkleri genellikle metal katyonları (+) verirken, kireç suyu/çöktürme testleriyle CO₃²⁻, Cl⁻, SO₄²⁻ gibi anyonlar (-) da tanınır.'),
  ('Laboratuvarda hidrojen (H₂) gazı suda çok az çözündüğü ve havadan çok hafif olduğu için tüpe hangi yöntemle toplanabilir?', 'Su üstünde toplama veya ağzı aşağı bakan (ters çevrilmiş) kuru deney tüpünde havayla yer değiştirme', ['Ağzı yukarı bakan açık beherglasta tabana çökmesini bekleyerek toplama', 'Berrak kireç suyunun içinde kimyasal olarak çöktürüp süzerek toplama', 'Derişik sülfürik asit içinde dondurup katı kristaller halinde toplama'], 'H₂ suda çözünmediğinden su dolu ters tüpte suyla yer değiştirerek veya havadan çok hafif (M = 2 g/mol) olduğundan ters tutulmuş tüpte yukarıda toplanır.'),
  ('Bir çözeltinin hem asitlik-bazlık sınıfını belirlemek hem de içindeki metal katyonunu tanımak isteyen bir öğrenci sırasıyla hangi iki basit yöntemi uygulayabilir?', 'İndikatör (turnusol/fenolftalein) testi ve platin telle alev deneyi', ['Ayrımsal kristallendirme ve mıknatısla ayırma işlemi', 'Santrifüjleme ve diyaliz zarından süzme işlemi', 'Kağıt kromatografisi ve dekantasyon (aktarma) işlemi'], 'Asit-baz karakteri indikatörlerle, alkali/toprak alkali ve bakır gibi metal katyonları ise karakteristik alev deneyiyle hızlıca tanınır.'),
  ('Aşağıdaki metal iyonu — alev deneyi rengi eşleştirmelerinden hangisi tamamen doğrudur?', 'Ca²⁺ : Tuğla kırmızısı', ['Na⁺ : Menekşe moru', 'K⁺ : Altın sarısı', 'Cu²⁺ : Kiremit kırmızısı'], 'Standart alev renklerinde Na⁺ sarı, K⁺ menekşe, Cu²⁺ mavi-yeşil, Ba²⁺ yeşil ve Ca²⁺ tuğla kırmızısıdır.'),
  ('Nitel (kalitatif) analiz ile nicel (kantitatif) analiz arasındaki temel fark aşağıdakilerden hangisidir?', 'Nitel analiz maddede hangi bileşenlerin bulunduğunu ("ne var?"), nicel analiz ise ne kadar bulunduğunu ("kaç gram/mol?") belirler', ['Nitel analiz yalnızca gazlara uygulanır, nicel analiz ise yalnızca katı metallere uygulanır', 'Nitel analizde terazi ve büret kullanılırken nicel analizde yalnızca koku ve tat duyusu kullanılır', 'Nitel analiz maddenin kütlesini ölçerken nicel analiz sadece maddenin fiziksel halini tahmin eder'], 'Alev testi ve gaz tanıma testleri "hangi iyon/gaz var?" sorusunu yanıtlayan nitel analiz; titrasyonla derişim bulma ise "ne kadar var?" sorusunu yanıtlayan nicel analizdir.'),
];
